-- Synthetic owners only; safe on hosted Postgres: every change rolls back.
begin;
create function pg_temp.ok(v boolean,label text)returns void language plpgsql as $$begin if v is not true then raise exception 'FAIL: %',label;end if;perform set_config('folio.removal_checks',(coalesce(nullif(current_setting('folio.removal_checks',true),''),'0')::int+1)::text,true);end$$;
create function pg_temp.no(statement text,label text)returns void language plpgsql as $$begin begin execute statement;exception when others then perform pg_temp.ok(true,label);return;end;raise exception 'FAIL: % accepted',label;end$$;
with u as(insert into auth.users(id,email,email_confirmed_at)values(gen_random_uuid(),'removal-a@example.invalid',now())returning id)select set_config('folio.ra',id::text,true)from u;
with u as(insert into auth.users(id,email,email_confirmed_at)values(gen_random_uuid(),'removal-b@example.invalid',now())returning id)select set_config('folio.rb',id::text,true)from u;
set local role authenticated;
select set_config('request.jwt.claim.sub',current_setting('folio.ra'),true);
select set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('folio.ra'),'is_anonymous',false)::text,true);
select public.initialize_workspace();
update public.profiles set tracking_start_date=null,monthly_living_budget_paise=100000 where id=current_setting('folio.ra')::uuid;
with a as(insert into public.accounts(name,type,opening_balance_paise,opening_date)values('Synthetic bank','bank',1000000,folio_private.today())returning id)select set_config('folio.rbank',id::text,true)from a;
with l as(insert into public.loans(name,principal_paise,apr,tenure_months,start_date,reported_emi_paise)values('Synthetic liability',100000,12,12,folio_private.today(),10000)returning id)select set_config('folio.rloan',id::text,true)from l;
select public.record_loan_payment(current_setting('folio.rloan')::uuid,current_setting('folio.rbank')::uuid,10000,1000,folio_private.today(),'Synthetic EMI',gen_random_uuid());
with s as(insert into public.subscriptions(name,amount_paise,cadence,next_due_on)values('Synthetic weekly',1201,'weekly',folio_private.today())returning id)select set_config('folio.rsub',id::text,true)from s;
insert into public.statement_rules(account_id,recipient_key,recipient_name,direction,kind,loan_id,amount_paise)values(current_setting('folio.rbank')::uuid,'synthetic-removal-lender','Synthetic lender','debit','loan_payment',current_setting('folio.rloan')::uuid,11000);
insert into public.statement_rules(account_id,recipient_key,recipient_name,direction,kind,category_id,subscription_id,amount_paise)values(current_setting('folio.rbank')::uuid,'synthetic-removal-merchant','Synthetic merchant','debit','expense',(select id from public.categories where kind='expense'limit 1),current_setting('folio.rsub')::uuid,1201);
select set_config('folio.rbefore',public.workspace_snapshot()::text,true);
select pg_temp.no(format('select public.remove_commitment(''loan'',%L,90000,100000,false,''wrong'')',current_setting('folio.rloan')),'explicit confirmation required');
select pg_temp.no(format('select public.remove_commitment(''loan'',%L,100000,100000,false,''DELETE'')',current_setting('folio.rloan')),'stale loan preview rejected');
select pg_temp.no(format('update public.loans set status=''closed'',removed_at=now()where id=%L',current_setting('folio.rloan')),'cannot bypass removal RPC');
select public.remove_commitment('loan',current_setting('folio.rloan')::uuid,90000,100000,false,'DELETE');
select public.remove_commitment('loan',current_setting('folio.rloan')::uuid,90000,100000,false,'DELETE');
select pg_temp.ok(jsonb_array_length(public.workspace_snapshot()->'loans')=0,'removed liability absent from current snapshot');
select pg_temp.ok(public.workspace_snapshot()->'summary'->>'existing_emi_paise'='0','EMI commitment removed');
select pg_temp.ok((public.workspace_snapshot()->'summary'->>'net_worth_paise')::bigint=(current_setting('folio.rbefore')::jsonb->'summary'->>'net_worth_paise')::bigint+90000,'net worth excludes explicitly removed liability');
select pg_temp.ok(public.workspace_snapshot()->'accounts'=current_setting('folio.rbefore')::jsonb->'accounts','removal never credits bank');
select pg_temp.ok((select count(*)=1 from public.loan_payments),'repayment history retained');
select pg_temp.ok((select count(*)=1 and sum(amount_paise)=-11000 from public.transactions),'recorded EMI cash outflow retained exactly once');
select pg_temp.ok((select bool_and(not enabled)from public.statement_rules where loan_id=current_setting('folio.rloan')::uuid),'linked EMI rules disabled');
select pg_temp.no(format('update public.loans set status=''active''where id=%L',current_setting('folio.rloan')),'removed loan cannot reopen');
select pg_temp.no(format('select public.record_loan_payment(%L,%L,1,0,folio_private.today(),'''',gen_random_uuid())',current_setting('folio.rloan'),current_setting('folio.rbank')),'new payment on removed loan rejected');
select pg_temp.no(format('update public.statement_rules set enabled=true where loan_id=%L',current_setting('folio.rloan')),'removed-target rule cannot re-enable');
select pg_temp.no(format('select public.remove_commitment(''subscription'',%L,5204,99999,true,''DELETE'')',current_setting('folio.rsub')),'stale living budget rejected');
select pg_temp.no(format('select public.remove_commitment(''subscription'',%L,1,100000,true,''DELETE'')',current_setting('folio.rsub')),'stale subscription amount rejected');
select public.remove_commitment('subscription',current_setting('folio.rsub')::uuid,5204,100000,true,'DELETE');
select public.remove_commitment('subscription',current_setting('folio.rsub')::uuid,5204,100000,true,'DELETE');
select pg_temp.ok((select monthly_living_budget_paise=94796 from public.profiles),'weekly cost annualised and rounded in paise; retry reduces budget only once');
select pg_temp.ok(jsonb_array_length(public.workspace_snapshot()->'subscriptions')=0,'subscription removed from upcoming schedule');
select pg_temp.ok((select not active and removed_at is not null from public.subscriptions where id=current_setting('folio.rsub')::uuid),'subscription history retained inactive');
select pg_temp.ok((select bool_and(not enabled)from public.statement_rules where subscription_id=current_setting('folio.rsub')::uuid),'subscription rules disabled');
with s as(insert into public.subscriptions(name,amount_paise,cadence,next_due_on)values('Synthetic annual',12000,'yearly',folio_private.today())returning id)select set_config('folio.rkeep',id::text,true)from s;
select public.remove_commitment('subscription',current_setting('folio.rkeep')::uuid,1000,94796,false,'DELETE');
select pg_temp.ok((select monthly_living_budget_paise=94796 from public.profiles),'keep-budget option preserves allowance');
with s as(insert into public.subscriptions(name,amount_paise,cadence,next_due_on)values('Synthetic high cost',200000,'monthly',folio_private.today())returning id)select set_config('folio.rhigh',id::text,true)from s;
select public.remove_commitment('subscription',current_setting('folio.rhigh')::uuid,200000,94796,true,'DELETE');
select pg_temp.ok((select monthly_living_budget_paise=0 from public.profiles),'budget floors at zero');
select pg_temp.ok((select count(*)>=1 from public.audit_events where table_name='loans'and entity_id=current_setting('folio.rloan')::uuid and after_data->>'removed_at'is not null),'loan removal audited');
select set_config('folio.rarchive',public.export_financial_data()::text,true);
select pg_temp.ok((current_setting('folio.rarchive')::jsonb->'data'->'loans'->0->>'removed_at')is not null,'portable export retains tombstones and linked history');
-- Another owner cannot remove the first owner's records or discover their values.
select set_config('request.jwt.claim.sub',current_setting('folio.rb'),true);
select set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('folio.rb'),'is_anonymous',false)::text,true);
select public.initialize_workspace();
select pg_temp.no(format('select public.remove_commitment(''loan'',%L,90000,0,false,''DELETE'')',current_setting('folio.rloan')),'cross-owner loan removal rejected');
select pg_temp.no(format('select public.remove_commitment(''subscription'',%L,5204,0,false,''DELETE'')',current_setting('folio.rsub')),'cross-owner subscription removal rejected');
select pg_temp.ok((select count(*)=0 from public.loans),'RLS hides other owners history');
select set_config('folio.rpreview',public.preview_financial_restore(current_setting('folio.rarchive')::jsonb)::text,true);
select pg_temp.ok((current_setting('folio.rpreview')::jsonb->>'can_restore')::boolean,'removed records and history pass restore rehearsal');
select public.confirm_financial_restore(current_setting('folio.rarchive')::jsonb,current_setting('folio.rpreview')::jsonb->>'archive_hash','RESTORE INTO EMPTY WORKSPACE',gen_random_uuid());
select pg_temp.ok(jsonb_array_length(public.workspace_snapshot()->'loans')=0 and jsonb_array_length(public.workspace_snapshot()->'subscriptions')=0,'restored tombstones remain excluded');
select pg_temp.ok((select count(*)=1 from public.loan_payments),'restored repayment links retained');
select pg_temp.ok((select count(*)=1 and sum(amount_paise)=-11000 from public.transactions),'restored cash outflow retained');
select pg_temp.ok((select count(*)=1 from public.loans where removed_at is not null),'restored removed loan retained for history');
-- Removing a card EMI must never erase the debt in its separate account.
with a as(insert into public.accounts(name,type,opening_balance_paise,opening_date)values('Synthetic card','credit_card',-50000,folio_private.today())returning id)select set_config('folio.rcard',id::text,true)from a;
with l as(insert into public.loans(name,principal_paise,apr,tenure_months,start_date,card_account_id)values('Synthetic card plan',20000,12,12,folio_private.today(),current_setting('folio.rcard')::uuid)returning id)select set_config('folio.rcardloan',id::text,true)from l;
select set_config('folio.rcardentry',public.record_entry(current_setting('folio.rcard')::uuid,(select id from public.categories where kind='expense'limit 1),'expense',1000,folio_private.today(),'Synthetic card deduction',null,gen_random_uuid())::text,true);
select public.link_card_emi_deduction(current_setting('folio.rcardloan')::uuid,current_setting('folio.rcardentry')::uuid);
select set_config('folio.rcardbefore',public.workspace_snapshot()::text,true);
select public.remove_commitment('loan',current_setting('folio.rcardloan')::uuid,20000,0,false,'DELETE');
select pg_temp.ok(public.workspace_snapshot()->'accounts'=current_setting('folio.rcardbefore')::jsonb->'accounts','card balance untouched by removal');
select pg_temp.ok(public.workspace_snapshot()->'summary'->>'net_worth_paise'=current_setting('folio.rcardbefore')::jsonb->'summary'->>'net_worth_paise','card debt remains in net worth');
select pg_temp.ok((select card_emi_loan_id=current_setting('folio.rcardloan')::uuid from public.transactions where id=current_setting('folio.rcardentry')::uuid),'historical card EMI link retained');
select pg_temp.no(format('select public.link_card_emi_deduction(%L,%L)',current_setting('folio.rcardloan'),current_setting('folio.rcardentry')),'removed plan rejects deduction links');
select current_setting('folio.removal_checks')as passed_removal_checks;
rollback;
